mod outer {
    fn secret() -> u32 {
        42
    }

    pub fn reveal() -> u32 {
        secret()
    }

    pub mod inner {
        pub fn peek() -> u32 {
            // a nested module may use its parent's private items
            super::secret() + 1
        }
    }
}

fn main() {
    println!("{} {}", outer::reveal(), outer::inner::peek());
}

