mod bank {
    pub struct Account {
        pub owner: String,
        balance: i64,
    }

    impl Account {
        pub fn new(owner: &str) -> Account {
            Account { owner: String::from(owner), balance: 0 }
        }

        pub fn deposit(&mut self, amount: i64) {
            self.balance += amount;
        }

        pub fn balance(&self) -> i64 {
            self.balance
        }
    }
}

fn main() {
    let mut acc = bank::Account::new("Ada");
    acc.deposit(40);
    println!("{} has {}", acc.owner, acc.balance());
}

use std::collections::HashMap;
use std::fmt::Result as FmtResult;
use std::io::Result as IoResult;

mod zoo {
    pub mod animals {
        pub enum Animal {
            Cat,
            Dog,
        }

        pub fn name(a: &Animal) -> String {
            match a {
                Animal::Cat => String::from("cat"),
                Animal::Dog => String::from("dog"),
            }
        }
    }

    pub mod show {
        use super::animals;
        use super::animals::Animal;

        pub fn line(a: Animal) -> String {
            format!("a {}", animals::name(&a))
        }
    }
}

use zoo::animals::Animal;
use zoo::show;

fn check_fmt() -> FmtResult {
    Ok(())
}

fn check_io() -> IoResult<u32> {
    Ok(7)
}

fn main() {
    println!("{}", show::line(Animal::Cat));
    println!("{}", show::line(Animal::Dog));

    let mut stock: HashMap<&str, u32> = HashMap::new();
    stock.insert("apple", 3);
    println!("{} {:?} {:?}", stock["apple"], check_fmt(), check_io());
}

